      zh: "\xE7\xBE\xBD\xE8\u203A\u2021\xE7\xA5\u017E\xE8\u02C6\u2021\xE5\u2026\u02C6\xE6\xB0\u2018\xE4\xB9\u2039\xE9\xAA\xA8"
