      zh: "\xE5\xA5\u2021\xE5\u2039\u017E\xE4\xBA\u017E\xE7\x81\xAB\xE5\xB1\xB1\xEF\xBC\u02C6\xE5\xA4\x8F\xE5\xA8\x81\xE5\xA4\xB7\xEF\xBC\u2030"
