      zh: "\xE6\u2039\u2030\xE7\xA5\u017E\xE5\xA4\u0153\xE8\u02C6\xAA\xE8\u02C6\u2021\xE5\xB7\xA8\xE8\u203A\u2021\xE9\u02DC\xBF\xE6\xB3\xA2\xE8\x8F\xB2\xE6\u2013\xAF"
