      zh: "\u5169\u5247\u683C\u9675\u862D\u77ED\u7BC7\u8D77\u6E90\u6545\u4E8B\uFF1A\u6E21\u9D09\u66FE\u80FD\u8AAA\u8A71\uFF0C\u7E3D\u662F\u53E3\u662F\u5FC3\u975E\uFF0C\u88AB\u6012\u8001\u4EBA\u8A2D\u6CD5\u6536\u56DE\u8AAA\u8A71\u4E4B\u80FD\uFF0C\u5F9E\u6B64\u53EA\u6703\u5636\u555E\u557C\u53EB\uFF1B\u59CA\u59B9\u7BC7\u4E2D\uFF0C\u6E21\u9D09\u5ACC\u68C4\u9D5D\u70BA\u5176\u9CE5\u7FBD\u756B\u4E0A\u7684\u82B1\u7D0B\uFF0C\u6FC0\u6012\u7684\u9D5D\u7D22\u6027\u5C07\u5176\u6F51\u6210\u4E00\u8EAB\u9ED1\uFF0C\u9019\u4FBF\u662F\u6E21\u9D09\u70CF\u9ED1\u7FBD\u6BDB\u7684\u7531\u4F86\u3002"
