      zh: "\u54C8\u5F97\u65AF\u5F97\u5B99\u65AF\u9ED8\u8A31\u64C4\u8D70\u73C0\u8033\u585E\u798F\u6D85\uFF1B\u5F97\u58A8\u5FD2\u8033\u61A4\u800C\u4EE4\u4E94\u7A40\u4E0D\u751F\uFF0C\u5B99\u65AF\u9042\u65A1\u65CB\uFF0C\u5973\u5152\u4E00\u5E74\u4E09\u5206\u4E4B\u4E8C\u5728\u4E16\u3001\u4E09\u5206\u4E4B\u4E00\u5C45\u51A5\u5E9C\uFF1B\u5973\u795E\u5275\u7ACB\u5384\u7409\u606F\u65AF\u79D8\u5100\uFF0C\u8A31\u5165\u5100\u8005\u8EAB\u5F8C\u5F97\u798F\u3002"
