      zh: "\u5A01\u9F4A\u6D1B\u6CE2\u5947\u7279\u5229\u65BC\u79D1\u963F\u7279\u4F69\u514B\u5C71\u964D\u751F\u8207\u79D1\u7D04\u723E\u6C99\u8D6B\u57FA\u4E4B\u6557"
