      zh: "\u79D1\u963F\u7279\u4F69\u514B\u300E\u86C7\u5C71\u300F\uFF1B\u8C61\u5FB5\u6027\u5B9A\u4F4D\u65BC\u58A8\u897F\u54E5\u57CE\u5927\u795E\u5EDF"
