      zh: "\u5929\u5E1D\u6853\u56E0\u9063\u5B50\u6853\u96C4\u964D\u65BC\u592A\u767D\u5C71\u795E\u6A80\u6A39\u4E0B\uFF0C\u4E3B\u7406\u4EBA\u9593\uFF1B\u718A\u8207\u864E\u6B32\u5316\u70BA\u4EBA\u2014\u2014\u60DF\u718A\u5FCD\u767E\u65E5\u827E\u849C\u4E4B\u82E6\u5316\u70BA\u5973\u5B50\u718A\u5973\uFF1B\u6853\u96C4\u5A36\u4E4B\uFF0C\u751F\u6A80\u541B\u738B\u5109\uFF1B\u6A80\u541B\u65BC\u516C\u5143\u524D2333\u5E74\u5EFA\u53E4\u671D\u9BAE\uFF0C\u5FA1\u4E16\u4E00\u5343\u4E94\u767E\u5E74\uFF0C\u5F8C\u96B1\u70BA\u5C71\u795E\u3002"
