    title: {
      en: "Baldr's Dreams: Odin Rides Down to Wake a Dead Seeress",
      zh: "\u5DF4\u723E\u5FB7\u4E4B\u5922\uFF1A\u5967\u4E01\u9A0E\u884C\u559A\u9192\u4EA1\u6545\u5973\u5148\u77E5"
    },
    tradition: "norse",
