      zh: "\u7DAD\u7A46\u723E\u6CB3\u5C0D\u5CB8\u7684\u84CB\u723E\u7F85\u5FB7\u4E4B\u5EF3\uFF08\u8C61\u5FB5\u6027\u5B9A\u4F4D\u65BC\u632A\u5A01\u5C24\u901A\u9ED1\u9580\u5C71\uFF09"
