    title: {
      en: "The Nine-Year Bl\xF3t and King Domaldi: Blood for the Harvest",
      zh: "\u4E5D\u5E74\u5927\u796D\u8207\u591A\u99AC\u723E\u8FEA\u738B\uFF1A\u4EE5\u8840\u63DB\u8C50\u5E74"
    },
    tradition: "norse",
    category: "myth-religion",
