      zh: "\u963F\u65AF\u52A0\u5FB7\u57CE\u7246\uFF08\u8C61\u5FB5\u6027\u5B9A\u4F4D\u65BC\u51B0\u5CF6\u8F9B\u683C\u97CB\u5FB7\u5229\uFF09"
