      zh: "\u5B89\u5FB7\u74E6\u5229\u7011\u5E03\u8207\u840A\u8335\u4E4B\u8DEF\uFF08\u8C61\u5FB5\u6027\u5B9A\u4F4D\u65BC\u840A\u8335\u6CB3\u8C37\uFF09"
