      zh: "\u4E00\u679A\u5C0F\u9285\u7247\u8B77\u7B26\u4E0A\u523B\u6709\u547C\u559A\u7D22\u723E\u7684\u5982\u5C3C\u8B77\u4F51\u5957\u8A9E\uFF1A\u6309\u6A19\u6E96\u91CB\u8B80\uFF0C\u4F69\u6234\u8005\u7948\u6C42\u96F7\u795E\u8B77\u4F51\uFF0C\u514D\u65BC\u71B1\u75C5\u8207\u6D77\u4E0A\u5147\u96AA\u3002\u6B64\u8A18\u9304\u662F\u8B77\u7B26\u6559\u7FA9\u7684\u5448\u73FE\uFF1A\u795E\u7684\u8B77\u4F51\u5316\u4F5C\u53EF\u4F69\u6234\u7684\u9298\u6587\uFF0C\u9019\u4E5F\u662F\u795E\u8A71\u8A9E\u6599\u4E2D\u6700\u76F4\u63A5\u5411\u7D22\u723E\u7948\u79B1\u7684\u5982\u5C3C\u6587\u737B\u3002"
