      zh: "\u683C\u5C3C\u5854\u6D77\u5FB7\u5DE8\u9F8D\u8352\u539F\uFF08\u8C61\u5FB5\u6027\u5B9A\u4F4D\u65BC\u840A\u8335\u6CB3\u8C37\uFF09"
