      zh: "\u53E6\u985E\u738B\u65CF\u4E16\u7CFB\u6A94\u6848\uFF1A\u9AD8\u8482\u7684\u760B\u72C2\u5317\u9A0E\uFF08\u8FFD\u9010\u7375\u9DF9\u885D\u4E0B\u61F8\u5D16\u2014\u2014\u760B\u7672\u958B\u57FA\uFF09\u3001\u61F8\u5D16\u738B\u570B\u4E4B\u6CD5\uFF08\u5976\u6C34\u77ED\u7F3A\u6642\u4EE5\u8001\u8005\u737B\u5D16\u2014\u2014\u5BB6\u65CF\u7684\u737B\u796D\u7D93\u6FDF\uFF09\u3001\u9AD8\u7279\u96F7\u514B\u958B\u5275\u9AD8\u7279\u4EBA\u4E00\u8108\uFF0C\u4EE5\u53CA\u6846\u67B6\u6545\u4E8B\uFF08\u5167\u5D4C\u65AF\u5854\u5361\u5FB7\u7684\u9752\u5E74\u7BC7\u7AE0\uFF1B\u8A6D\u8A08\u8005\u96F7\u592B\u7684\u8D08\u79AE\u93C8\uFF09\u3002\u6B64\u8A18\u9304\u662F\u53E6\u985E\u958B\u57FA\u6A94\u6848\u3002"
