    id: "hindu-mahabharata-markandeya-pralaya",
    title: {
      en: "Markandeya's Vision of the Dissolution",
      zh: "\u6469\u6839\u5FB7\u8036\u898B\u52AB\u6EC5\u4E4B\u7570\u8C61"
    },
