      zh: "\u706B\u5DE8\u4EBA\u6A94\u6848\uFF08\u672B\u65E5\u4E4B\u6230\u4E4B\u5916\uFF09\uFF1A\u8607\u723E\u7279\u81EA\u300C\u958B\u95E2\u4E4B\u521D\u300D\u5373\u5B88\u885B\u4E16\u754C\u908A\u7DE3\uFF08\u300A\u5C45\u723E\u83F2\u7684\u5E7B\u60D1\u300B\u5275\u4E16\u7AE0\u7684\u5B9A\u4F4D\uFF09\u3001\u540D\u7269\u5B78\uFF08surtr \u610F\u70BA\u300C\u7126\u9ED1\u8005\u300D\u2014\u2014\u7164\u7159\u5DE8\u4EBA\u4E4B\u7A31\uFF09\u3001\u300A\u6D1B\u57FA\u7684\u5435\u7F75\u300B\u4E2D\u7684\u706B\u4E4B\u81EA\u8FF0\uFF08\u6D1B\u57FA\uFF1A\u300C\u6211\u66FE\u7ABA\u898B\u7A46\u65AF\u8C9D\u723E\u7684\u5EF3\u5802\u2014\u2014\u706B\u65CF\u7684\u8239\u8207\u5175\u5668\u300D\uFF09\u3001Muspell \u4E00\u8A5E\u5728\u65AF\u582A\u7684\u7D0D\u7DAD\u4E9E\u4E4B\u5916\u7684\u53E4\u5FB7\u8A9E\u6587\u737B\u300AMuspilli\u300B\u672B\u65E5\u8A69\u4E2D\u7684\u51FA\u73FE\uFF0C\u4EE5\u53CA\u5176\u5B9A\u4F4D\u4E4B\u722D\uFF08\u7A46\u65AF\u8C9D\u723E\u70BA\u672C\u571F\u65E5\u8033\u66FC\u672B\u4E16\u89C0\uFF0C\u6291\u6216\u57FA\u7763\u6559\u6642\u4EE3\u8F38\u5165\uFF09\u3002\u6B64\u8A18\u9304\u662F\u706B\u5DE8\u4EBA\u96F6\u7C21\u6A94\u6848\u3002"
