    id: "hindu-vishnu-purana-vamana-bali",
    title: {
      en: "The Dwarf's Three Steps: Vamana and King Bali",
      zh: "\u4F8F\u5112\u7684\u4E09\u6B65\uFF1A\u7B4F\u6469\u90A3\u8207\u5A46\u5229\u738B"
    },
    tradition: "hindu",
    category: "myth-religion",
