      zh: "\u57C3\u53CA\u5E95\u6BD4\u65AF\u5E1D\u738B\u8C37\uFF08\u585E\u63D0\u4E00\u4E16\u9675\u5893\uFF0C\u5929\u725B\u4E4B\u66F8\u523B\u58C1\u8655\uFF09"
