    tradition: "chinese",
    category: "myth",
    region: {
      en: "Lion-Camel Ridge and Lion-Camel Kingdom, eight hundred li of bones (pin: mythic westward route)",
      zh: "\u7345\u99DD\u5DBA\u3001\u7345\u99DD\u570B"
    },
