      zh: "\u6CE2\u65AF\u738B\u5967\u5EAB\u65AF\u6BBA\u963F\u5339\u65AF\u8056\u725B\u4EE5\u5BB4\u5BA2\uFF1B\u57C3\u53CA\u796D\u53F8\u65BC\u738B\u8868\u4E0D\u4EE5\u540D\u8A18\u4E4B\uFF0C\u800C\u4EE5\u4E00\u67C4\u300E\u528D\u300F\u4E4B\u5716\u50CF\u8A18\u5176\u4EBA\u2014\u2014\u795E\u8056\u6587\u5B57\u8A18\u5176\u54C1\u6027\u800C\u975E\u5176\u4EBA\uFF0C\u5C60\u795E\u8005\u9042\u6210\u6BC0\u6EC5\u4E4B\u5668\u3002"
