      zh: "\u5854\u592B\u5948\u8D6B\u7279\u738B\u9060\u5F81\u6642\u98DF\u5175\u5352\u4E4B\u7C97\u98DF\u3001\u81E5\u65BC\u8D64\u5730\uFF0C\u9042\u751F\u51FA\u5C0D\u5109\u6A38\u4E4B\u6DF1\u60C5\uFF0C\u5F97\u796D\u53F8\u4E4B\u8A31\uFF0C\u65BC\u5E95\u6BD4\u65AF\u795E\u5EDF\u7ACB\u67F1\uFF0C\u523B\u6EFF\u8A5B\u5492\u2014\u2014\u5492\u90A3\u7B2C\u4E00\u4F4D\u4F7F\u57C3\u53CA\u4EBA\u96E2\u5109\u6A38\u751F\u6D3B\u4E4B\u738B\u7F8E\u5C3C\u65AF\u3002"
