      zh: "\u57C3\u53CA\u6751\u838A\u8207\u73BB\u4FC4\u63D0\u4E9E\uFF08\u72C4\u4FC4\u502A\u7D22\u65AF\u796D\u7940\u4E4B\u50B3\u64AD\uFF09"
