    motifs: [
      "taboo-transgression",
      "boon-curse"
    ],
    sensitivity: {
      restricted: false,
      note: "Ancient folk aition via Herodotus; no living community restrictions."
    },
    passages: [
      {
        id: "1",
        text: "Cheops moreover came, they said, to such a pitch of wickedness, that being in want of money he caused his own daughter to sit in the stews, and ordered her to obtain from those who came a certain amount of money (how much it was they did not tell me); but she not only obtained the sum appointed by her father, but also she formed a design for herself privately to leave behind her a memorial, and she requested each man who came in to her to give her one stone upon her building: and of these stones, they told me, the pyramid was built which stands in front of the great pyramid in the middle of the three, each side being one hundred and fifty feet in length.",
        note: "Verbatim excerpt of Macaulay, Herodotus (1890), Book II.126."
      }
    ],
