    license: "Public domain (translation 1910)",
    summary: {
      en: "The dead face crocodiles from all four quarters of the river and answer them with identity-spells \u2014 'Get thee back, thou Crocodile of the West... I am set... I am Osiris... I am Sept... I am Tem' \u2014 until the climax of pure solar self-protection: 'Created things are in the hollow of my hand, and the things that are not yet made are inside me... I am Ra, the self-protected, no evil thing whatsoever shall overthrow me.'",
      zh: "\u4EA1\u8005\u56DB\u9762\u9047\u9C77\uFF0C\u4EE5\u540C\u9AD4\u4E4B\u5492\u61C9\u4E4B\u2014\u2014\u300E\u9000\u53BB\u5427\uFF0C\u897F\u65B9\u4E4B\u9C77\u2026\u2026\u6211\u5DF2\u5B9A\u3002\u6211\u662F\u5967\u897F\u91CC\u65AF\u2026\u2026\u6211\u662F\u585E\u666E\u7279\u2026\u2026\u6211\u662F\u963F\u5716\u59C6\u300F\u2014\u2014\u672B\u53E5\u4E43\u7D14\u7CB9\u592A\u967D\u5F0F\u81EA\u8B77\u5BA3\u8A00\uFF1A\u300E\u5DF2\u6210\u4E4B\u7269\u5728\u6211\u638C\u5FC3\uFF0C\u672A\u6210\u4E4B\u7269\u5728\u6211\u61F7\u4E2D\u2026\u2026\u6211\u5373\u62C9\uFF0C\u81EA\u8B77\u8005\uFF0C\u4EFB\u4F55\u90AA\u60E1\u7686\u4E0D\u80FD\u52DD\u6211\u3002\u300F"
    },
    motifs: [
      "transformation",
      "theophany"
    ],
    sensitivity: {
      restricted: false,
      note: "Ancient funerary spells; no living community restrictions."
    },
    passages: [
      {
        id: "1",
        text: "Away with thee! Retreat! Get back, O thou accursed Crocodile Sui. Thou shalt not come nigh me, for I have life through the words of power that are in me. If I utter thy name to the Great God he will make thee to come before the two divine messengers Betti and Herkemmaat. Heaven ruleth its seasons, and the spell hath power over what it mastereth, and my mouth ruleth the spell that is inside it. My teeth which bite are like flint knives, and my teeth which grind are like unto those of the Wolf-god. O thou who sittest spellbound with thine eyes fixed through my spell, thou shalt not carry off my spell, thou Crocodile that livest on spells.",
        note: "Verbatim excerpt of Budge, Literature of the Ancient Egyptians (1910), ch. IV, Book of the Dead ch. 31."
      },
      {
        id: "2",
        text: "Get thee back, thou Crocodile of the West, that livest on the never-resting stars. That which is thy taboo is in me. I have eaten the brow (or, skull) of Osiris. I am set. \u2014 Get thee back, thou Crocodile of the East. The serpent Nau is inside me. I will set it on thee, thy flame shall not approach me... Get thee back, thou Crocodile of the South... I will fetter thee. My charm is among the reeds. I will not yield unto thee. \u2014 Get thee back, thou Crocodile of the North... I am Tem. \u2014 Created things are in the hollow of my hand, and the things that are not yet made are inside me. I am clothed in and supplied with thy spells, O Ra, which are above me and beneath me. I am Ra, the self-protected, no evil thing whatsoever shall overthrow me.",
        note: "Verbatim excerpt of Budge (1910), Book of the Dead ch. 32."
      }
    ],
    persons: [
      "ra",
      "osiris",
      "anubis"
    ]
