      zh: "\u975E\u6D32\u4F86\u4E4B\u602A\u8A95\u5BB6\u5B85\u795E\uFF1A\u8C9D\u65AF\u77EE\u800C\u81C2\u9577\u817F\u66F2\uFF0C\u8033\u5982\u8C93\u3001\u9B1A\u9AEE\u84EC\u7136\uFF0C\u62AB\u7378\u76AE\u66F3\u5C3E\u2014\u2014\u70BA\u6230\u795E\u3001\u62B1\u7434\u4E4B\u6A02\u795E\u3001\u4EA6\u662F\u611B\u795E\uFF0C\u6046\u4EE5\u6B63\u50CF\u793A\u4EBA\uFF1B\u4EE3\u723E\u5DF4\u54C8\u91CC\u6700\u53E4\u4E4B\u50CF\u4E2D\u4F8D\u54C8\u7279\u8B1D\u666E\u8607\u7279\u8A95\u751F\uFF0C\u65BC\u963F\u62DC\u591A\u65AF\u6709\u795E\u8AED\uFF0C\u53C8\u70BA\u54C8\u6CE2\u514B\u62C9\u7279\u65AF\u4E4B\u4E73\u4FDD\uFF0C\u8B77\u5B30\u795E\u800C\u788E\u86C7\u300E\u65BC\u9F52\u9593\u300F\u3002"
