      zh: "\u91CC\u5361\u591A\u4E0A\u5B78\u537B\u5728\u86D9\u5858\u300E\u82E6\u8B80\u300F\uFF0C\u4EE5\u86D9\u9CF4\u70BA\u8AA6\u7D93\uFF1B\u5B78\u5F97\u300E\u51E1\u767C\u81ED\u8005\u5FC5\u6B7B\u300F\u7684\u6559\u8A13\u5F8C\uFF0C\u4ED6\u81EA\u8A8D\u5DF2\u6B7B\uFF0C\u8EBA\u5728\u719F\u756A\u77F3\u69B4\u4E0B\u54C0\u5606\u4E0D\u6562\u5403\u3002\u5F97\u77E5\u7236\u89AA\u70BA\u4E03\u9996\u5DE8\u4EBA\u6240\u6BBA\u3001\u59B9\u59B9\u88AB\u64C4\u5F8C\uFF0C\u4ED6\u5F97\u5169\u74F6\u795E\u6C34\uFF08\u4E00\u74F6\u8B77\u9AD4\u3001\u4E00\u74F6\u596A\u529B\uFF09\u8207\u98DB\u978D\uFF0C\u8A85\u5DE8\u4EBA\u3001\u91CB\u56DA\u5F92\uFF0C\u5A36\u9732\u897F\u4E9E\u70BA\u59BB\u3002"
