      zh: "\u5341\u4E00\u738B\u596A\u666E\u85A9\u7F8E\u63D0\u79D1\u65AF\u4E4B\u6B0A\u800C\u9010\u4E4B\u65BC\u6CBC\u6FA4\u2014\u2014\u56E0\u5176\u7121\u91D1\u76C2\uFF0C\u4E43\u4EE5\u9285\u76D4\u5960\u9152\uFF0C\u9069\u61C9\u795E\u8AED\uFF1B\u5E03\u6258\uFF08\u5168\u57C3\u53CA\u6700\u9748\u4E4B\u795E\u8AED\uFF09\u8A31\u4E4B\uFF1A\u300E\u53CA\u6D77\u4E0A\u9285\u4EBA\u51FA\uFF0C\u5FA9\u4EC7\u5FC5\u81F3\u300F\u2014\u2014\u65E2\u800C\u8863\u9285\u7532\u4E4B\u4F0A\u5967\u5C3C\u4E9E\u8207\u5361\u91CC\u4E9E\u4EBA\u56E0\u52AB\u63A0\u6F02\u81F3\uFF0C\u666E\u85A9\u7F8E\u63D0\u79D1\u65AF\u8207\u4E4B\u5584\uFF0C\u9042\u50BE\u5341\u4E00\u738B\u800C\u738B\u5168\u57C3\u53CA\u3002"
