    license: "Public domain (Roys 1933, not renewed at US Copyright Office)",
    summary: {
      en: "The sky is set in its place by the first pope, the burden of Katun 13 Ahau \u2014 but the face of the sun shall be turned from its course and turned face down in the reign of the perishable rulers. For five days the sun is eclipsed, and then the torch of Katun 13 Ahau is seen: God's sign that death shall come to the rulers of the land and the first rulers driven from their towns.",
      zh: "\u9996\u4EFB\u6559\u7687\u2014\u2014\u5341\u4E09\u963F\u8D6B\u5361\u7279\u502B\u4E4B\u91CD\u8CA0\u2014\u2014\u5C07\u5929\u7A7A\u5B89\u7F6E\u65BC\u5176\u4F4D\uFF1B\u7136\u800C\u5728\u673D\u58DE\u7D71\u6CBB\u8005\u7684\u671D\u4EE3\uFF0C\u65E5\u9762\u5C07\u504F\u96E2\u5176\u8ECC\u3001\u7FFB\u8EAB\u671D\u4E0B\u3002\u592A\u967D\u8755\u6C92\u4E94\u65E5\uFF0C\u5176\u5F8C\u5341\u4E09\u963F\u8D6B\u5361\u7279\u502B\u7684\u706B\u70AC\u986F\u73FE\uFF1A\u6B64\u4E43\u4E0A\u5E1D\u4E4B\u5146\uFF0C\u5BA3\u544A\u6B7B\u4EA1\u5FC5\u81E8\u6B64\u5730\u7D71\u6CBB\u8005\uFF0C\u6700\u521D\u7684\u738B\u5C07\u88AB\u9010\u51FA\u5176\u57CE\u3002"
    },
    motifs: [
      "prophetic-vision",
      "world-renewal",
      "sun-capture"
    ],
    sensitivity: {
      restricted: false,
      note: "Published colonial-era text; quote/paraphrase of Roys public-domain translation only."
    },
    passages: [
      {
        id: "1",
        text: "Then the sky was put in its place, Corporales ti ojales, by the first pope, the face of the katun, the burden of the Katun 13 Ahau. The face of the sun shall be turned from its course, it shall be turned face down during the reign of the perishable men, the perishable rulers.",
        note: "Quoted from Roys translation (1933), ch. XI; lightly condensed; not verbatim throughout."
      },
      {
        id: "2",
        text: "Five days the sun is eclipsed, and then shall be seen the torch of Katun 13 Ahau, a sign given by God that death shall come to the rulers of this land. Thus it shall come about that the first rulers are driven from their towns. Then Christianity shall have come here to the land. The descendants of the former rulers are dishonored and brought to misery; we are christianized, while they treat us like animals.",
        note: "Condensed from Roys translation (1933), ch. XI; not verbatim throughout."
      }
    ],
