    passages: [
      {
        id: "1",
        text: "Padre Cogolludo, who visited this temple in 1656, is the first to complain of the steep staircase, which caused his head to swim. He found in one of these apartments offerings of cocoa and copal which had been burnt very recently; consequently, fifteen years after the Conquest the natives were still sacrificing to their gods, and practising their superstitions in their own temples.",
        note: "Condensed from Charnay (1887) quoting Cogolludo; not verbatim throughout."
      }
    ],
