      zh: "\u5948\u53CA\u5229\u4E9E\u4F0A\u8CBB\u57CE\uFF08\u4FEE\u88DC\u7834\u788E\u5929\u5730\u846B\u8606\u7684\u738B\u5BAE\u524D\u5EAD\uFF09"
