      zh: "\u6258\u5361\u6B66\u6B66\u4EFF\u5144\u64F2\u6930\uFF0C\u7136\u5176\u6930\u4EE5\u5E95\u89F8\u5730\uFF0C\u7206\u51FA\u4E8C\u5973\uFF0C\u9F3B\u6A11\u4F4E\u584C\u8C8C\u919C\u3002\u4ED6\u5AC9\u5992\u5144\u4E4B\u7F8E\u59BB\uFF0C\u9042\u68C4\u5DF1\u4E8C\u59BB\uFF0C\u800C\u596A\u6258\u5361\u6BD4\u7D0D\u90A3\u4E4B\u4E00\u59BB\u3002"
