      zh: "\u9996\u5973\u4F0A\u7F85\u7DAD\u723E\u52A0\u52D2\u4E43\u5361\u7279\u4EE5\u67D4\u679D\u8207\u74B0\u6240\u9020\uFF0C\u5982\u88FD\u5361\u5716\u5100\u5F0F\u9AD8\u5E3D\u4E4B\u6CD5\uFF1A\u7D2E\u74B0\u65BC\u679D\u3001\u8986\u4EE5\u897F\u7C73\u68D5\u6ADA\u8449\u9798\u3002\u5176\u540D\u53D6\u81EA vil\uFF08\u7D2E\uFF09\u8207 gale\uFF08\u9A19\uFF09\u3002\u65E2\u6210\uFF0C\u5361\u7279\u898B\u5176\u5FAE\u5FAE\u4E00\u7B11\uFF0C\u4FBF\u77E5\u6B64\u70BA\u6D3B\u5973\u5B50\u3002"
