      zh: "\u74E6\u52AA\u963F\u5716\u73ED\u514B\u65AF\u7FA4\u5CF6\u70CF\u96F7\u5E15\u62C9\u5E15\u62C9\u5CF6\uFF08\u8C61\u5FB5\u5B9A\u4F4D\uFF09"
