      zh: "\u5361\u99AC\u4F0A\u57FA\u5229\u4E9E\u6708\u521D\u4E00,\u65B0\u53D7\u6B66\u7684\u54C8\u5357\u5EAB\u65AF\u79D1\u8207\u70CF\u6797\u5EAB\u65AF\u79D1\u5169\u4E16\u7CFB\u9A0E\u58EB\u5404\u57F7\u540A\u7D22\u5165\u5927\u5EE3\u5834,\u4E92\u64F2\u300C\u79D1\u79D1\u300D(\u4E00\u7A2E\u858A\u4E0A\u7684\u7C7D\u5BE6),\u6642\u6216\u8FD1\u8EAB\u89D2\u529B\u4EE5\u8F03\u81C2\u529B,\u76F4\u81F3\u5728\u5834\u7684\u5370\u52A0\u738B\u8D77\u8EAB\u559D\u6B62\u3002\u6B64\u8B02\u300C\u55AC\u5361\u7D0D\u79D1\u300D,\u8F03\u529B\u4E4B\u6232,\u4EE5\u8A66\u8AB0\u6700\u5F37\u6700\u52C7\u3002"
