    sensitivity: {
      restricted: false,
      note: "Folk tale."
    },
    passages: [
      {
        id: "1",
        text: "An old merchant owes the Tsar of the Sea a debt of magic and is dragged down beneath the waters; his daughter Vassilissa is sent with him to learn what the sea-tsar wants. She meets the sea-tsar's daughter, the wise Vassilissa, who pities her and teaches her what the court demands.",
        note: "Paraphrase of Curtin (1890), 'Vassilissa the Cunning, and the Tsar of the Sea'; not verbatim."
      },
      {
        id: "2",
        text: "The mortal hero who comes to the rescue is told by the sea-tsar's daughter to answer the riddle, spin the invisible wheel, and change into the silver dove and the golden one, so that the sea-tsar's three tests are each met. The lover is saved three times \u2014 by the daughter's cunning, by his own patience, and by the waters themselves, which bear him home. He marries her, and the sea's debt is paid.",
        note: "Paraphrase of Curtin (1890); not verbatim."
      }
    ],
