    sensitivity: {
      restricted: false,
      note: "Daina."
    },
    passages: [
      {
        id: "1",
        text: "In comparison with the sun the moon is a very minor figure in the dainas, and his chief importance is his connexion with her. When his spouse reproaches him for his pale colour, he replies that while she shines for man by day, he can only look at himself by night in the water.",
        note: "Paraphrase of Gray, Baltic Mythology, Mythology of All Races III (1918), Part V; not verbatim."
      },
      {
        id: "2",
        text: "He wears a mantle of stars, and \u2014 like the sun \u2014 is liable to be destroyed, that is, eclipsed, by dragons, serpents, and witches; the pale moon is the sky's bridegroom in exile, spending his nights at the water's edge where the reflection of his own light is the only face he has.",
        note: "Paraphrase of Gray (1918); not verbatim."
      }
    ],
    persons: []
