    passages: [
      {
        id: "1",
        text: "She dwells on a mountain \u2014 the vault of heaven \u2014 and standing in mid-sky she reproves her daughters because one had not swept the floor, while the other had failed to wash the table. In the dainas heaven is not a throne-room but a working kitchen, and the Sun is the housewife of the day.",
        note: "Paraphrase of Gray, Baltic Mythology, Mythology of All Races III (1918), Part V; not verbatim."
      },
      {
        id: "2",
        text: "The daughters she scolds are the twilights; the floor of heaven unswept is a sky full of cloud. The song is sung at the loom and the wash-tub in the Latvian farmhouses, where the same scolding is given every morning to the daughters of the house \u2014 for the daughters of Saule and the daughters of the farm are one family in the songs.",
        note: "Paraphrase of Gray (1918); not verbatim."
      }
    ],
    persons: []
