    sensitivity: {
      restricted: false,
      note: "Folk belief."
    },
    passages: [
      {
        id: "1",
        text: "Besides the Poludnica the Russians have a field-spirit named Polevik or Polevoy, about the height of a corn-stalk until harvest-time, when he shrivels to the size of stubble. He runs away before the swing of the scythe and hides among the stalks that are still standing; when the last ears are cut he gets into the hands of the reaper and is brought to the barn with the final sheaf.",
        note: "Paraphrase of Machal, Slavic Mythology, Mythology of All Races III (1918), Part I ch. 8; not verbatim."
      },
      {
        id: "2",
        text: "He appears at noon or before sunset, and at that time it is unsafe to take a nap in the field: the Polevik, roaming about on horseback, will ride over those who are sleeping there, or will send disease upon them. The field is his until the last sheaf is carried in.",
        note: "Paraphrase of Machal (1918); not verbatim."
      }
    ],
