      zh: "\u6D1B\u8AFE\u4F0A\u5361\u99AC\u5361\u5E0C\u57FA\u822A\u884C\u74E6\u80E1\uFF0C\u8207\u5361\u5EAB\u5E0C\u9ED1\u74E6\u738B\u9023\u756A\u8F03\u85DD\uFF1A\u5148\u5F08\u9ED1\u767D\u68CB\u4E00\u5C40\uFF0C\u7E7C\u800C\u4E8C\u81F3\u4E94\u5C40\uFF0C\u6700\u5F8C\u8CED\u4E0A\u88AB\u514B\u74E6\u7DAD\u52AA\u4F0A\u963F\u70CF\u7C73\u6240\u8A85\u914B\u9577\u9AB8\u9AA8\u7684\u85CF\u533F\u4E4B\u8655\u3002\u9023\u9023\u5F97\u52DD\u5F8C\uFF0C\u6D1B\u8AFE\u63ED\u51FA\u7955\u846C\u4E4B\u5730\uFF0C\u8FD4\u590F\u5A01\u5937\u5E73\u670D\u53DB\u81E3\u2014\u2014\u7559\u7D66\u5361\u5EAB\u5E0C\u9ED1\u74E6\u7684\u53EA\u6709\u68CB\u76E4\u524D\u7684\u7F9E\u8FB1\u3002"
