      zh: "\u91AB\u8005\u4E4B\u821F\u884C\u7D93\u6CB3\u5CB8\u4E4B\u969B\uFF0C\u5DE8\u8072\u5BA3\u544A\u773E\u4EBA\u9808\u9589\u6236\u4E0D\u51FA\uFF1B\u9055\u8005\u7ACB\u5373\u6583\u547D\u3002\u7FCC\u65E5\u5C0B\u5F97\u8A72\u821F\uFF0C\u5169\u7AEF\u5404\u7761\u8457\u4E00\u4F4D\u5947\u7570\u4E4B\u4EBA\uFF1B\u5DE8\u8072\u518D\u8A00\uFF1A\u8A85\u6B64\u4E8C\u7269\uFF0C\u5C07\u5927\u6709\u76CA\u65BC\u5370\u7B2C\u5B89\u4EBA\u3002\u773E\u4EBA\u8A98\u5176\u5165\u9130\u8FD1\u8B70\u5C4B\uFF0C\u6BBA\u800C\u711A\u4E4B\u2014\u2014\u83F8\u8349\u4E4B\u682A\u81EA\u5176\u7070\u71FC\u4E2D\u9577\u51FA\u3002"
