    sensitivity: {
      restricted: false,
      note: "|Xam San lore from the Bleek & Lloyd archive; presented as an archival record."
    },
    passages: [
      {
        id: "1",
        text: "The Rainbow is yellow in that part which lies above; the piece which seems red lies below. For the Mantis, who is also yellow, lies above, and Kwammang-a lies below. For the Mantis is the one whose part above is yellow, and that part which lies below is red, while that part which is above is yellow. It is the Rainbow. Men call it Kwammang-a. Therefore we who are children say 'Kwammang-a' to it, because the grown-up people said Kwammang-a to it... Then people say: 'The Rainbow stands yonder and the rain will break.'",
        note: "Quote from D. F. Bleek, The Mantis and His Friends (1924), p. 66 (public domain)."
      }
    ],
