      zh: "\u5357\u975E\u5317\u958B\u666E\u7701\u54C8\u5766\u59C6\u6CB3\u8207\u5E03\u4EC0\u66FC\u862D\uFF08\u8C61\u5FB5\u5B9A\u4F4D\uFF09"
