    license: "Public domain (Rockhill translation 1884)",
    summary: {
      en: "Summoned to free the great tree blocking Kapilavastu's water, the prince is first tested in the gardens by Devadatta shooting a goose overhead; it falls in the Bodhisattva's garden, who extracts the arrow and binds the wound - and refuses to give up the bird: it belongs not to him who attempted to take its life, but to him who saved it. This was the first quarrel between the two.",
      zh: "\u83E9\u85A9\u61C9\u53EC\u70BA\u57CE\u6C11\u79FB\u9664\u5835\u6C34\u7684\u5927\u6A39\uFF1B\u9014\u7D93\u5712\u6797\uFF0C\u63D0\u5A46\u9054\u591A\u4E00\u7BAD\u5C04\u843D\u5929\u4E0A\u98DB\u96C1\uFF0C\u96C1\u843D\u5165\u83E9\u85A9\u5712\u4E2D\u3002\u83E9\u85A9\u70BA\u5176\u62D4\u7BAD\u88F9\u50B7\uFF0C\u4E26\u62D2\u7D55\u4EA4\u51FA\uFF1A\u96C1\u5C6C\u65BC\u6551\u5176\u547D\u8005\uFF0C\u4E0D\u5C6C\u65BC\u6B32\u5BB3\u5176\u547D\u8005\u2014\u2014\u4E8C\u4EBA\u7D50\u6028\u7531\u6B64\u800C\u59CB\u3002"
    },
    motifs: [
      "taboo-transgression",
      "parable-teaching",
      "temptation",
      "bodhisattva"
    ],
    sensitivity: {
      restricted: false,
      note: "Canonical narrative; paraphrase of public-domain translation."
    },
    passages: [
      {
        id: "1",
        text: "While they were still in the gardens Devadatta saw a goose flying overhead, so he shot it, and it fell in the Bodhisattva's garden; he took it, extracted the arrow and bound up its wound. Devadatta sent a messenger to claim the bird, but the Bodhisattva would not give it up, saying that it belonged not to him who had attempted to take its life, but to him who had saved it - and this was the first quarrel between these two.",
        note: "Paraphrase of Rockhill, The Life of the Buddha (1884); not verbatim."
      }
    ],
    persons: [
      "buddha",
      "devadatta"
    ]
