    license: "Public domain (1817)",
    summary: {
      en: "Journeying through the island, Aji Saka met the dead bodies of two Rakshasas, each holding a leaf with an inscription on it \u2014 one in purwa (ancient) characters, the other in Siamese. He united the two inscriptions and thus formed the Javan alphabet of twenty letters. He then fought several combats with the Rakshasas, particularly one Demata Chingkar, before returning to Astina with a written account of all he had seen and done.",
      zh: "\u963F\u5409\xB7\u85A9\u5361\u884C\u904D\u5CF6\u4E2D\uFF0C\u9047\u7F85\u524E\u5C4D\u9AB8\u4E8C\u5177\uFF0C\u5404\u6301\u4E00\u8449\uFF0C\u8449\u4E0A\u5404\u6709\u9298\u6587\u2014\u2014\u4E00\u70BA\u53E4\u5B57\uFF08purwa\uFF09\uFF0C\u4E00\u70BA\u66B9\u7F85\u5B57\u3002\u4ED6\u5408\u4E8C\u9298\u800C\u5275\u722A\u54C7\u4E8C\u5341\u5B57\u6BCD\u3002\u5176\u5F8C\u6578\u8207\u7F85\u524E\u6230\u2014\u2014\u5C24\u8207\u300E\u5FB7\u746A\u5854\xB7\u6B3D\u5361\u723E\u300F\u6FC0\u9B25\u2014\u2014\u7136\u5F8C\u6B78\u963F\u65AF\u63D0\u90A3\u5FA9\u547D\u3002"
    },
    motifs: [
      "wisdom-sacrifice",
      "culture-hero"
    ],
    sensitivity: {
      restricted: false,
      note: "Alphabet-origin myth; the demon's script becoming human letters is a distinctive Javanese etiology."
    },
    passages: [
      {
        id: "1",
        text: "In his progress through the island he met with the dead bodies of two Rakshasas, each holding a leaf with an inscription on it, one in purwa (ancient), the other in Siamese characters: these he united, and thus formed the Javan alphabet of twenty letters.",
        note: "Paraphrase of Raffles, History of Java (1817), vol. II ch. X; not verbatim."
      },
      {
        id: "2",
        text: "He had several combats with the Rakshasas, particularly with one Demata Chingkar; and after fixing the date of his different discoveries and leaving mementos of his visit wherever he went, he finally returned to Astina and delivered to his sovereign a written account of all he had seen and done.",
        note: "Paraphrase of Raffles, History of Java (1817), vol. II ch. X; not verbatim."
      }
    ],
    persons: []
