      zh: "\u4E94\u5B50\u6016\u8ECD\u8207\u5DE8\u4EBA\u65CF\u96C5\u6797\u6BD4\u6240\u751F\u4E4B\u5B30\u6208\u9640\u5361\u67E5\uFF0C\u5929\u751F\u795E\u529B\uFF1B\u5176\u5916\u7956\u7236\u6012\u6B64\u7570\u5146\uFF0C\u5C07\u5B30\u5B69\u64F2\u5411\u5929\u7A7A\u2014\u2014\u5B30\u5152\u81EA\u96F2\u9704\u589C\u5730\u800C\u5927\u5730\u4E0D\u88C2\uFF08\u54C7\u63DA\u6232\u5B9A\u5F0F\uFF09\u3002\u5F8C\u65BC\u5929\u754C\u53D7\u8A13\uFF0C\u6210\u70BA\u300E\u82E6\u695D\u5165\u9AA8\u300F\u300E wired bones\u300F\u4E4B\u98DB\u884C\u6230\u58EB\u2014\u2014\u822C\u5EA6\u8ECD\u4E4B\u7A7A\u8ECD\u3002"
