    passages: [
      {
        id: "1",
        text: "In Girah lives the widow Calon Arang, keeper of the leyak arts; her daughter Ratna Manggali is beautiful, but no man dares marry into the witch's house, and the widow's humiliation hardens into a grudge against the whole country. Sickness pours out of Girah into the land of King Airlangga; people die beyond the reach of arms and prayer, until the court understands that the plague is a woman's art turned loose.",
        note: "Paraphrase of the Pararaton's Calon Arang episode; not verbatim. / Paraphrase of the Pararaton episode; not verbatim."
      },
      {
        id: "2",
        text: "The king sends the ascetic Mpu Barada in disguise to learn the widow's art; at the height of her ritual dance he strikes her down, the sickness dies with her, and Girah is burnt to the ground so that nothing of the witch's village remains.",
        note: "Paraphrase of the Pararaton episode; not verbatim."
      }
    ],
