      zh: "\u4E7E\u6DB8\u5CFD\u8C37\uFF0C\u5F8C\u6210\u54E5\u502B\u6BD4\u4E9E\u6CB3\uFF0C\u83EF\u76DB\u9813\u5DDE\uFF08\u8C61\u5FB5\u5B9A\u4F4D\uFF09"
