    passages: [
      {
        id: "1",
        text: "In Sundanese tradition the last great king of Pakuan Pajajaran, Prabu Siliwangi, is remembered as the archetype of the just ruler of the Parahyangan \u2014 the 'land of the gods' \u2014 his name the standard by which later West Javanese courts claimed authority.",
        note: "Paraphrase of Sundanese dynastic tradition as preserved in the chronicle material recorded by Raffles (1817) and later collections; not verbatim."
      },
      {
        id: "2",
        text: "Tradition credits him with refusing submission when the kingdom fell, withdrawing from the capital into the mountains, and remaining thereafter a hidden presence in the highlands \u2014 the vanished king who legitimizes every shrine and court that invokes his name.",
        note: "Paraphrase of Sundanese dynastic tradition; not verbatim."
      }
    ],
