      zh: "\u8457\u540D\u7F8E\u4EBA\u838E\u62DC\xB7\u5357\xB7\u963F\u9B6F\u4F0A\u96A8\u8001\u7236\uFF08\u6EAB\u548C\u7684\u7A46\u6CE2\xB7\u62C9\u4F50\xB7\u5357\xB7\u85A9\u9B6F\u591A\uFF09\u8015\u65BC\u7530\u9593\uFF1B\u6027\u66B4\u7684\u5927\u914B\u9577\u62C9\u4F50\xB7\u5DF4\u73ED\u4E01\uFF08\u8607\u57C3\xB7\u5E15\u53E4\uFF09\u7D22\u5979\u70BA\u59BB\uFF1B\u8001\u7236\u6297\u62D2\uFF0C\u914B\u9577\u7ADF\u6BBA\u4E4B\u3002\u838E\u62DC\u65BC\u8C37\u4E2D\u9752\u5E74\u4E4B\u9996\u62FF\u8D77\u7236\u89AA\u7684\u7375\u69CD\uFF0C\u9060\u8DDD\u4E00\u69CD\u6583\u914B\u9577\uFF1B\u62D2\u7D55\u4E00\u5207\u5A5A\u7D04\uFF0C\u6210\u70BAkaba\u50B3\u8AAA\u4E2D\u89AA\u624B\u4E86\u7D50\u4EC7\u6028\u7684\u5973\u5152\u3002"
