      zh: "\u62C9\u5F17\u723E\u65AF\u4E4B\u5831\u544A\u4EBA\u4EE5\u300E\u5C3C\u70CF\u963F\u76AE\u5FB7\u300F\u9F4B\u6212\u6536\u675F\u5DF4\u91D0\u66C6\u6CD5\u2014\u2014\u300E\u6B77\u4E00\u665D\u591C\uFF0C\u5176\u9593\u7981\u98DF\u7981\u7720\u300F\uFF0C\u884C\u65BC\u6BCF\u6708\u4E4B\u9996\u6216\u5341\u4E94\u65E5\u3002\u6B64\u5373\u975C\u9ED8\u65E5\uFF08Nyepi\uFF09\u4E4B\u6700\u65E9\u8A18\u9304\u2014\u2014\u5DF4\u91D0\u65B0\u5E74\u59CB\u65BC\u5168\u5CF6\u6B62\u606F\uFF1A\u7184\u706B\u6EC5\u71C8\u3001\u505C\u6B62\u52DE\u4F5C\uFF0C\u4F7F\u5DE1\u5CF6\u4E4B\u9B54\u9748\u898B\u5CF6\u7A7A\u7121\u4E00\u4EBA\u800C\u904E\u3002"
