      zh: "\u5DF4\u67E5\u67E5\u862D\u8207\u99AC\u5353\u5E15\u5E0C\u7279\u5169\u8ECD\u6703\u65BC\u5CF6\u4E4B\u4E2D\u90E8\uFF0C\u5927\u6230\u4E0D\u5206\u52DD\u8CA0\uFF1B\u6B63\u7576\u5169\u738B\u5C07\u8981\u89AA\u81EA\u6C7A\u9B25\u4E4B\u969B\uFF0C\u96D9\u65B9\u5354\u5B9A\uFF1A\u81EA\u6B64\u4EE5\u897F\u8AF8\u5730\u5C6C\u5DF4\u67E5\u67E5\u862D\u3001\u4EE5\u6771\u5C6C\u99AC\u5353\u5E15\u5E0C\u7279\u2014\u2014\u81EA\u4E3B\u67F1\u77F3\u5411\u5357\u756B\u4E00\u76F4\u7DDA\u70BA\u754C\uFF0C\u7ACB\u67F1\u4EE5\u7D00\u6B64\u7D04\u3002\u8A72\u67F1\u81F3\u4ECA\u7336\u5B58\u65BC\u4E09\u5BF6\u74CF\u4EE5\u897F\u6578\u91CC\u4E4B\u63D0\u5409\u52D2\u3002"
