    source: {
      archive: "Project Gutenberg",
      work: "Charles Hose & William McDougall, The Pagan Tribes of Borneo (1912), the batu tuloi of the Kenyah altar-posts",
      url: "https://www.gutenberg.org/cache/epub/3307/pg3307.txt"
    },
    license: "Public domain (1912)",
    summary: {
      en: "Peculiar adjuncts of the Kenyah altar-posts are the deep-red dracaena plant and a number of large spherical stones, the batu tuloi \u2014 perpetual possessions of the house. Their history is unknown; they are supposed to grow gradually larger and to move spontaneously when danger threatens the house; and when a household removes to build a new home, the stones are carried to the new site with some ceremony.",
      zh: "\u80AF\u96C5\u796D\u67F1\u65C1\u6709\u6DF1\u7D05\u9F8D\u8840\u6A39\u8207\u6578\u679A\u5927\u5713\u77F3\u2014\u2014\u5DF4\u5716\xB7\u5716\u6D1B\u4F0A\uFF0C\u70BA\u5BB6\u5B85\u6C38\u50B3\u4E4B\u7269\u3002\u5176\u4F86\u6B77\u7121\u4EBA\u77E5\u66C9\uFF1B\u76F8\u50B3\u5176\u9AD4\u6F38\u9577\uFF0C\u4E14\u65BC\u5BB6\u5B85\u6709\u96AA\u6642\u81EA\u884C\u79FB\u52D5\uFF1B\u5BB6\u6236\u9077\u5C45\u5EFA\u65B0\u5C4B\u4E4B\u65E5\uFF0C\u8AF8\u77F3\u9808\u884C\u79AE\u9077\u5F80\u65B0\u5740\u3002"
    },
    motifs: [
      "sacred-place",
      "transformation",
      "ritual-origin"
    ],
    sensitivity: {
      restricted: false,
      note: "Animate-stone possession record; paraphrase respectfully."
    },
    passages: [
      {
        id: "1",
        text: "Peculiar adjuncts of the altar-posts of the Kenyahs are the dracaena plant and a number of large spherical stones, batu tuloi; these are perpetual possessions of the house, whose history is unknown, but they are supposed to grow gradually larger and to move spontaneously when danger threatens the house. When a household removes and builds for itself a new home, these stones are carried with some ceremony to the new site \u2014 the house's luck travelling with its stones.",
        note: "Paraphrase of Hose & McDougall (1912); not verbatim."
      }
    ],
    persons: []
