    sensitivity: {
      restricted: false,
      note: "Canonical scripture of a living tradition; quoted from public-domain JPS 1917. Hagar's story is also foundational in Islamic tradition (record cross-referenced there)."
    },
    passages: [
      {
        id: "1",
        text: "And the angel of the LORD found her by a fountain of water in the wilderness, by the fountain in the way to Shur. And he said: 'Hagar, Sarai's handmaid, whence camest thou? and whither goest thou?' And she said: 'I flee from the face of my mistress Sarai.'",
        note: "Verbatim: JPS 1917, Genesis 16:7-8 (public domain)."
      },
      {
        id: "2",
        text: "The angel promised that her seed would be multiplied beyond counting and named the boy Ishmael, 'God hears'. Hagar answered the first naming-theology in the Bible: 'Thou art a God that seest' \u2014 for she said, 'Have I even here seen Him that seeth me?' She returned and bore Abram a son in his eighty-sixth year. Paraphrase of Genesis 16:10-16 (JPS 1917); not verbatim.",
        note: "Paraphrase of Genesis 16:10-16 (JPS 1917); not verbatim."
      }
    ],
    persons: [
      "abraham",
      "sarah",
      "hagar"
    ]
