    sensitivity: {
      restricted: false,
      note: "Canonical scripture of a living tradition; quoted from public-domain JPS 1917. Later tradition read this as the paradigm of cruelty to strangers; the record states the narrative without endorsing later moralizations."
    },
    passages: [
      {
        id: "1",
        text: "And they called unto Lot, and said unto him: 'Where are the men that came in to thee this night? bring them out unto us, that we may know them.' And Lot went out unto them to the door, and shut the door behind him.",
        note: "Verbatim: JPS 1917, Genesis 19:5-6 (public domain)."
      },
      {
        id: "2",
        text: "Lot pleaded with the crowd as 'brethren' and offered his two daughters, but the men of Sodom pressed upon him. The angels pulled Lot inside, shut the door, and smote everyone at the entrance with blindness, 'both small and great', so that they wearied themselves finding the door. Paraphrase of Genesis 19:8-11 (JPS 1917); not verbatim.",
        note: "Paraphrase of Genesis 19:8-11 (JPS 1917); not verbatim."
      }
    ],
    persons: []
