    sensitivity: {
      restricted: false,
      note: "Canonical scripture of a living tradition; quoted from public-domain JPS 1917."
    },
    passages: [
      {
        id: "1",
        text: "And it came to pass, when they had brought them forth abroad, that he said: 'Escape for thy life; look not behind thee, neither stay thou in all the Plain; escape to the mountain, lest thou be swept away.' The sun rose as Lot entered Zoar, and the LORD rained upon Sodom and Gomorrah brimstone and fire out of heaven, overthrowing the cities and all the plain. Lot's wife looked back from behind him and became a pillar of salt. Abraham rose early that morning and looked down to see the smoke of the land going up as the smoke of a furnace \u2014 'and God remembered Abraham, and sent Lot out of the midst of the overthrow'. Paraphrase of Genesis 19:23-29 (JPS 1917); not verbatim.",
        note: "Verbatim: JPS 1917, Genesis 19:17 (public domain). / Paraphrase of Genesis 19:23-29 (JPS 1917); not verbatim."
      }
    ],
    persons: [
      "abraham"
    ]
