    sensitivity: {
      restricted: false,
      note: "Canonical scripture of a living tradition; quoted from public-domain JPS 1917."
    },
    passages: [
      {
        id: "1",
        text: "And Sarah said: 'God hath made laughter for me; every one that heareth will laugh on account of me.' And she said: 'Who would have said unto Abraham, that Sarah should give children suck? for I have borne him a son in his old age.'",
        note: "Verbatim: JPS 1917, Genesis 21:6-7 (public domain)."
      },
      {
        id: "2",
        text: "The LORD visited Sarah as He had promised; she conceived and bore Abraham a son at the set time God had spoken. Abraham named him Isaac and circumcised him on the eighth day, being a hundred years old. Sarah weaned him, and Abraham made a great feast the day Isaac was weaned. Paraphrase of Genesis 21:1-8 (JPS 1917); not verbatim.",
        note: "Paraphrase of Genesis 21:1-8 (JPS 1917); not verbatim."
      }
    ],
    persons: [
      "abraham",
      "sarah",
      "isaac"
    ]
