      zh: "\u96C5\u5404\u61FC\u4EE5\u6383\u56DB\u767E\u4EBA\uFF0C\u5C07\u5BB6\u7737\u8CA1\u7269\u6E21\u904E\u96C5\u535A\u6CB3\uFF0C\u7368\u81EA\u7559\u4E0B\uFF1B\u6709\u500B\u4EBA\u8207\u4ED6\u6454\u8DE4\u76F4\u5230\u9ECE\u660E\uFF0C\u6478\u5176\u5927\u817F\u7AA9\uFF0C\u96C5\u5404\u7DCA\u6293\u4E0D\u653E\u6C42\u795D\u798F\u2014\u2014\u300C\u4F60\u7684\u540D\u4E0D\u8981\u518D\u53EB\u96C5\u5404\uFF0C\u8981\u53EB\u4EE5\u8272\u5217\uFF0C\u56E0\u70BA\u4F60\u8207\u795E\u8207\u4EBA\u8F03\u529B\uFF0C\u90FD\u5F97\u4E86\u52DD\u3002\u300D\u96C5\u5404\u540D\u5176\u5730\u70BA\u6BD7\u52AA\u4F0A\u52D2\uFF1A\u300C\u6211\u9762\u5C0D\u9762\u898B\u4E86\u795E\uFF0C\u6211\u7684\u6027\u547D\u4ECD\u5F97\u4FDD\u5168\u300D\uFF0C\u5F9E\u6B64\u7638\u817F\uFF1B\u4EE5\u8272\u5217\u4EBA\u4E0D\u5403\u5927\u817F\u7AA9\u7684\u7B4B\u3002\u7FCC\u65E5\u5144\u5F1F\u76F8\u64C1\u800C\u6CE3\u3002"
