      zh: "\u4EE5\u8272\u5217\u70BA\u7D04\u745F\u4F5C\u5F69\u8863\uFF0C\u5341\u4E03\u6B72\u7684\u5C11\u5E74\u9023\u5F97\u4E8C\u5922\u2014\u2014\u79BE\u6346\u4E0B\u62DC\uFF0C\u65E5\u6708\u5341\u4E00\u661F\u4E0B\u62DC\u2014\u2014\u62DB\u81F4\u5144\u9577\u5AC9\u6068\u3002\u5949\u7236\u547D\u8D74\u591A\u574D\u63A2\u671B\uFF0C\u5144\u9577\u5011\u525D\u5176\u5F69\u8863\uFF0C\u6295\u4E4B\u65BC\u7121\u6C34\u7684\u5751\uFF0C\u7D93\u7336\u5927\u63D0\u8B70\uFF0C\u4EE5\u4E8C\u5341\u820D\u5BA2\u52D2\u9280\u5B50\u8CE3\u7D66\u4EE5\u5BE6\u746A\u5229\u5546\u4EBA\u3002\u773E\u5144\u4EE5\u7F8A\u7F94\u8840\u67D3\u5F69\u8863\uFF0C\u96C5\u5404\u4E0D\u80AF\u53D7\u5B89\u6170\uFF1A\u300C\u6211\u5FC5\u60B2\u54C0\u8457\u4E0B\u9670\u9593\u5230\u6211\u5152\u5B50\u90A3\u88CF\u3002\u300D"
