      zh: "\u300C\u4E0D\u8A8D\u8B58\u7D04\u745F\u7684\u65B0\u738B\u300D\u58D3\u8FEB\u4EE5\u8272\u5217\uFF0C\u4E0B\u4EE4\u6EBA\u6BBA\u5E0C\u4F2F\u4F86\u7537\u5B30\uFF1B\u6536\u751F\u5A46\u65BD\u5F17\u62C9\u8207\u666E\u963F\u656C\u754F\u795E\u800C\u4E0D\u5F9E\u3002\u5229\u672A\u5973\u5B50\u85CF\u5B50\u4E09\u6708\uFF0C\u5F8C\u5C07\u5176\u653E\u5165\u5857\u77F3\u6F06\u77F3\u6CB9\u7684\u8606\u8466\u7BB1\uFF0C\u7F6E\u65BC\u6CB3\u908A\u8606\u837B\u4E2D\u3002\u6CD5\u8001\u5973\u5152\u767C\u73FE\u5B30\u5B69\uFF0C\u52D5\u4E86\u6190\u61AB\u4E4B\u5FC3\uFF1B\u5176\u59CA\u6A5F\u654F\u53EC\u4F86\u751F\u6BCD\u4EE3\u54FA\u3002\u516C\u4E3B\u70BA\u5176\u547D\u540D\u6469\u897F\u2014\u2014\u300C\u56E0\u6211\u628A\u4ED6\u5F9E\u6C34\u88CF\u62C9\u51FA\u4F86\u300D\u3002"
