      zh: "\u5169\u540D\u63A2\u5B50\u591C\u5BBF\u57CE\u7246\u4E0A\u7684\u5993\u5973\u5587\u5408\u5BB6\u4E2D\uFF1B\u738B\u6D3E\u4EBA\u6349\u62FF\u6642\uFF0C\u5979\u5C07\u4ED6\u5011\u85CF\u5728\u623F\u9802\u7684\u9EBB\u79F8\u4E2D\uFF0C\u5F15\u8FFD\u6355\u8005\u5F80\u6E21\u53E3\u53BB\u3002\u5979\u627F\u8A8D\u7D05\u6D77\u7684\u795E\u8E5F\u65E9\u5DF2\u4EE4\u8FE6\u5357\u4EBA\u5FC3\u90FD\u6D88\u5316\u2014\u2014\u300C\u8036\u548C\u83EF\u4F60\u5011\u7684\u795E\u672C\u662F\u4E0A\u5929\u4E0B\u5730\u7684\u795E\u300D\u2014\u2014\u4FBF\u70BA\u5168\u5BB6\u8A0E\u547D\u3002\u4F7F\u8005\u4EE5\u8A93\u8A00\u8207\u7A97\u4E0A\u7684\u6731\u7D05\u7DDA\u7E69\u70BA\u6191\u3002\u99AC\u592A\u798F\u97F3\u5C07\u5979\u5217\u70BA\u57FA\u7763\u5148\u7956\uFF0C\u5E0C\u4F2F\u4F86\u66F8\u8207\u96C5\u5404\u66F8\u7686\u5F15\u5176\u4FE1\u5FC3\u8207\u884C\u70BA\u3002"
