      zh: "\u88AB\u64C4\u4E4B\u5730\u8FE6\u5DF4\u9B6F\u6CB3\u908A\uFF0C\u5929\u5411\u796D\u53F8\u4EE5\u897F\u7D50\u958B\u4E86\uFF1A\u5317\u65B9\u98B3\u4F86\u65CB\u98A8\uFF0C\u706B\u4E2D\u6519\u8457\u5149\u8F1D\uFF1B\u56DB\u6D3B\u7269\u5404\u6709\u56DB\u81C9\u2014\u2014\u4EBA\u3001\u7345\u3001\u725B\u3001\u9DF9\u2014\u2014\u65C1\u6709\u300C\u8F2A\u4E2D\u5957\u8F2A\u300D\u7684\u8F2A\u5B50\uFF0C\u6EFF\u5708\u6709\u773C\uFF0C\u9748\u5F80\u54EA\u88CF\u53BB\u5C31\u76F4\u884C\u3002\u7A79\u84BC\u4E4B\u4E0A\u5F77\u5F7F\u85CD\u5BF6\u77F3\u5BF6\u5EA7\uFF0C\u5176\u4E0A\u6709\u8036\u548C\u83EF\u69AE\u8000\u7684\u5F62\u50CF\u2014\u2014\u795E\u7684\u540C\u5728\u7531\u6B64\u88AB\u5E36\u5165\u88AB\u64C4\u4E4B\u5730\uFF0C\u4E5F\u6210\u70BA\u897F\u65B9\u5929\u754C\u5716\u50CF\u7684\u6E90\u982D\uFF08\u555F\u793A\u9304\u4E2D\u7684\u56DB\u6D3B\u7269\u518D\u73FE\u6B64\u666F\uFF09\u3002"
