    sensitivity: {
      restricted: false,
      note: "Canonical scripture of a living tradition; quoted from public-domain JPS 1917."
    },
    passages: [
      {
        id: "1",
        text: "Thy servant my father said unto us: 'Ye know that my wife bare me two sons; and the one went out from me, and I said: Surely he is torn in pieces; and I saw him not since.' ... Now therefore when I come to thy servant my father, and the lad be not with us; seeing that his life is bound up in the lad's life; it shall come to pass, when he seeth that the lad is not with us, that he will die.",
        note: "Verbatim: JPS 1917, Genesis 44:27-31 (public domain), condensed with ellipsis."
      },
      {
        id: "2",
        text: "'Let thy servant, I pray thee, abide instead of the lad a bondman to my lord; and let the lad go up with his brethren. For how shall I go up to my father, if the lad be not with me?' The man who had once proposed selling his brother now gave himself in exchange \u2014 and the test of the brothers was passed. Paraphrase of Genesis 44:33-34 (JPS 1917); not verbatim.",
        note: "Paraphrase of Genesis 44:33-34 (JPS 1917); not verbatim."
      }
    ],
    persons: [
      "judah",
      "joseph",
      "jacob"
    ]
