    sensitivity: {
      restricted: false,
      note: "Canonical scripture of a living tradition; quoted from public-domain JPS 1917. Read on the fast day following Yom Kippur haftarah cycle."
    },
    passages: [
      {
        id: "1",
        text: "And he took the calf which they had made, and burnt it with fire, and ground it to powder, and strewed it upon the water, and made the children of Israel drink of it. And Moses said unto Aaron: 'What did this people unto thee, that thou hast brought a great sin upon them?'",
        note: "Verbatim: JPS 1917, Exodus 32:20-21 (public domain)."
      },
      {
        id: "2",
        text: "While the people feasted, the LORD told Moses: 'Go, get thee down; for thy people have corrupted themselves'. Moses prayed \u2014 'Turn from Thy fierce wrath, and repent of this evil against Thy people... Remember Abraham, Isaac, and Israel' \u2014 and 'the LORD repented of the evil which He said He would do'. Descending with Joshua, Moses heard the singing, saw the calf and the dancing, and hurled the tablets down, shattering them at the mountain's foot. He stood in the gate crying: 'Whoso is on the LORD's side, come unto me!' and the sons of Levi gathered to him. Paraphrase of Exodus 32:7-29 (JPS 1917); not verbatim.",
        note: "Paraphrase of Exodus 32:7-29 (JPS 1917); not verbatim."
      }
    ],
    persons: [
      "moses",
      "aaron"
    ]
