    lat: 30.2,
    lon: 34.8,
    period: "Composite narrative, composed c. 8th-5th c. BCE; principal MS: Leningrad Codex B19a (1008 CE)",
    source: {
      archive: "Sefaria (JPS 1917 translation)",
      work: "Numbers 11:16-30, JPS Tanakh 1917",
      url: "https://www.sefaria.org/Numbers.11.16"
    },
    license: "Public domain (JPS 1917)",
    summary: {
      en: "Burdened by the people's weeping for meat, Moses cries: 'I am not able to bear all this people alone'. God tells him to gather seventy elders at the tent; the spirit that rests on him is placed on them, and they prophesy \u2014 but do not continue. Two men left in the camp, Eldad and Medad, prophesy in the camp itself; Joshua would have them restrained, and Moses answers with the ideal of shared prophecy: 'Would God that all the LORD's people were prophets.'",
      zh: "\u767E\u59D3\u56E0\u8981\u8089\u800C\u6CE3\uFF0C\u6469\u897F\u547C\u66F0\uFF1A\u300C\u7BA1\u7406\u9019\u767E\u59D3\u7684\u8CAC\u4EFB\u592A\u91CD\u4E86\uFF0C\u6211\u7368\u81EA\u7576\u4E0D\u8D77\u3002\u300D\u795E\u547D\u65BC\u5E55\u524D\u96C6\u4E03\u5341\u9577\u8001\uFF1B\u964D\u65BC\u6469\u897F\u7684\u9748\u5206\u8207\u4E4B\uFF0C\u4ED6\u5011\u53D7\u611F\u8AAA\u8A71\u2014\u2014\u537B\u4E0D\u518D\u7E7C\u7E8C\u3002\u71DF\u4E2D\u9084\u6709\u4F0A\u52D2\u9054\u7C73\u9054\u4E8C\u4EBA\u53D7\u611F\u8AAA\u8A71\uFF1B\u7D04\u66F8\u4E9E\u6B32\u7981\u4E4B\uFF0C\u6469\u897F\u4EE5\u5171\u627F\u9810\u8A00\u4E4B\u7406\u60F3\u7B54\uFF1A\u300C\u60DF\u9858\u8036\u548C\u83EF\u7684\u767E\u59D3\u90FD\u53D7\u611F\u8AAA\u8A71\u3002\u300D"
    },
    motifs: [
      "spirit-possession",
      "oracle-divination",
      "prophetic-vision",
      "doom-foretold"
    ],
    sensitivity: {
      restricted: false,
      note: "Canonical scripture of a living tradition; quoted from public-domain JPS 1917."
    },
    passages: [
      {
        id: "1",
        text: "And there ran a young man, and told Moses, and said: 'Eldad and Medad do prophesy in the camp.' And Joshua the son of Nun, the minister of Moses from his youth up, answered and said: 'My lord Moses, restrain them.' And Moses said unto him: 'Enviest thou for my sake? would God that all the LORD's people were prophets, that the LORD would put His spirit upon them!'",
        note: "Verbatim: JPS 1917, Numbers 11:27-29 (public domain)."
      }
    ],
    persons: [
      "moses"
    ]
