      zh: "\u795E\u81EA\u6BD8\u65AF\u8FE6\u5C71\u9802\u5C07\u61C9\u8A31\u5168\u5730\u6307\u793A\u6469\u897F\u2014\u2014\u300C\u6211\u4F7F\u4F60\u773C\u775B\u770B\u898B\u4E86\uFF0C\u4F60\u537B\u4E0D\u5F97\u904E\u53BB\u90A3\u88E1\u300D\u2014\u2014\u6700\u5049\u5927\u7684\u5148\u77E5\u6B7B\u65BC\u8A72\u5730\uFF0C\u5E74\u4E00\u767E\u4E8C\u5341\uFF0C\u300C\u4EE5\u5F8C\u4EE5\u8272\u5217\u4E2D\u518D\u6C92\u6709\u8208\u8D77\u5148\u77E5\u50CF\u6469\u897F\u7684\u300D\u3002\u4ED6\u846C\u65BC\u300C\u6469\u62BC\u5730\u2026\u2026\u4F2F\u6BD8\u73E5\u5C0D\u9762\u7684\u8C37\u4E2D\uFF1B\u53EA\u662F\u5230\u4ECA\u65E5\u6C92\u6709\u4EBA\u77E5\u9053\u4ED6\u7684\u58B3\u5893\u300D\u3002"
