    sensitivity: {
      restricted: false,
      note: "Canonical scripture of a living tradition; quoted from public-domain JPS 1917. Shema recited twice daily; tefillin and mezuzah are living ritual obligations derived from these verses."
    },
    passages: [
      {
        id: "1",
        text: "Hear, O Israel: the LORD our God, the LORD is one. And thou shalt love the LORD thy God with all thy heart, and with all thy soul, and with all thy might. And these words, which I command thee this day, shall be upon thy heart... And thou shalt bind them for a sign upon thy hand, and they shall be for frontlets between thine eyes. And thou shalt write them upon the door-posts of thy house, and upon thy gates.",
        note: "Verbatim: JPS 1917, Deuteronomy 6:4-9 (public domain), condensed."
      },
      {
        id: "2",
        text: "And thou shalt come unto the priest... and say: 'I profess this day unto the LORD thy God, that I am come unto the land which the LORD swore unto our fathers for to give us.' And thou shalt say: 'A wandering Aramean was my father; and he went down into Egypt... and the LORD brought us forth out of Egypt with a mighty hand, and with an outstretched arm... and He hath brought us into this place, and hath given us this land, a land flowing with milk and honey.' Paraphrase of Deuteronomy 26:3-9 (JPS 1917); not verbatim.",
        note: "Paraphrase of Deuteronomy 26:3-9 (JPS 1917); not verbatim."
      }
    ],
    persons: [
      "moses"
    ]
