      zh: "\u5728\u7D93\u4E2D\u63D0\u53CA\u6613\u5FB7\u91CC\u65AF\uFF1B\u4ED6\u662F\u6B63\u76F4\u8005\uFF0C\u662F\u5148\u77E5\uFF1B\u6211\u628A\u4ED6\u64E2\u5347\u5230\u4E00\u500B\u9AD8\u8655\u3002\u4E26\u6613\u53F8\u99AC\u5100\u3001\u6613\u5FB7\u91CC\u65AF\u3001\u5DE6\u52D2\u84CB\u723E\u83F2\u723E\u2014\u2014\u4ED6\u5011\u90FD\u662F\u5805\u5FCD\u8005\uFF1B\u6211\u4F7F\u4ED6\u5011\u9032\u5165\u6211\u7684\u6069\u6148\uFF0C\u56E0\u70BA\u4ED6\u5011\u662F\u6B63\u76F4\u8005\u3002"
