    passages: [
      {
        id: "1",
        text: "And the king said to Doeg: 'Turn thou, and fall upon the priests.' And Doeg the Edomite turned, and he fell upon the priests, and slew on that day fourscore and five persons that did wear a linen ephod. And Nob, the city of the priests, smote he with the edge of the sword, both men and women, children and sucklings, and oxen and asses and sheep, with the edge of the sword.",
        note: "Verbatim: JPS 1917, 1 Samuel 22:18-19 (public domain)."
      }
    ],
    persons: [
      "david",
      "saul"
    ]
