    source: {
      archive: "Sefaria (JPS 1917 translation)",
      work: "2 Samuel 6, JPS Tanakh 1917",
      url: "https://www.sefaria.org/2_Samuel.6.1"
    },
    license: "Public domain (JPS 1917)",
    summary: {
      en: "Bringing the ark up from Kirjath-jearim on a new cart, Uzzah touches it to steady it and dies 'beside the ark of God'. David fears the LORD's presence and defers the journey; three months later it is carried properly, with sacrifices every six paces. The king leaps and dances before the ark in a linen ephod \u2014 Michal's scorn at 'the base fellow exposing himself' earns her childlessness.",
      zh: "\u81EA\u57FA\u5217\u8036\u7433\u4EE5\u65B0\u8ECA\u904B\u6AC3\uFF0C\u70CF\u6492\u6276\u6AC3\u800C\u7ACB\u6583\u300C\u5728\u795E\u7684\u7D04\u6AC3\u65C1\u300D\u3002\u5927\u885B\u61FC\u8036\u548C\u83EF\u4E4B\u81E8\uFF0C\u4E2D\u6B62\u884C\u7A0B\uFF1B\u4E09\u6708\u5F8C\u4EE5\u6B63\u6CD5\u62AC\u884C\uFF0C\u6BCF\u516D\u6B65\u737B\u796D\u3002\u541B\u738B\u7A7F\u7D30\u9EBB\u5E03\u4EE5\u5F17\u5F97\u5728\u6AC3\u524D\u8E34\u8E8D\u8DF3\u821E\u2014\u2014\u7C73\u7532\u8B4F\u5176\u300C\u9732\u9AD4\u300D\u5982\u611A\u5984\u4EBA\uFF0C\u56E0\u800C\u7121\u5B50\u5230\u6B7B\u3002"
    },
    motifs: [
      "taboo-transgression",
      "ritual-origin",
      "sacred-kingship"
    ],
    sensitivity: {
      restricted: false,
      note: "Canonical scripture of a living tradition; quoted from public-domain JPS 1917."
    },
    passages: [
      {
        id: "1",
        text: "And it was so, that, when they that bore the ark of the LORD had gone six paces, he sacrificed an ox and a fatling. And David danced before the LORD with all his might; and David was girded with a linen ephod. So David and all the house of Israel brought up the ark of the LORD with shouting, and with the sound of the horn.",
        note: "Verbatim: JPS 1917, 2 Samuel 6:13-15 (public domain)."
      }
    ],
    persons: [
      "david",
      "bathsheba"
    ]
