      zh: "\u5148\u77E5\u5922\u4E2D\u5728\u5929\u623F\u8655\uFF0C\u898B\u4E00\u4EBA\u7E5E\u884C\uFF0C\u53E6\u4E00\u4EBA\u8207\u4E4B\u540C\u884C\u3002\u4ED6\u554F\u6B64\u4E8C\u4EBA\u70BA\u8AB0\uFF0C\u7B54\u66F0\uFF1A\u9AD8\u5927\u7D05\u819A\u3001\u7259\u5982\u8C61\u7259\u8005\u662F\u6613\u535C\u62C9\u6B23\uFF1B\u8207\u4E4B\u540C\u884C\u8005\u8C8C\u4F3C\u6BD4\u62C9\u52D2\u2014\u2014\u662F\u6A02\u5712\u7684\u5BA3\u79AE\u54E1\u3002\u9192\u5F8C\u5148\u77E5\u8AAA\uFF1A\u300E\u9019\u662F\u6BD4\u62C9\u52D2\uFF0C\u9AD8\u5927\u8005\u662F\u6613\u535C\u62C9\u6B23\uFF1A\u6211\u5DF2\u898B\u6A02\u5712\u7684\u5BA3\u79AE\u53CA\u5176\u5BA3\u79AE\u54E1\u3002\u300F"
