    license: "Public domain (JPS 1917)",
    summary: {
      en: "Ahab covets Naboth's ancestral vineyard beside his palace; Naboth refuses \u2014 'The LORD forbid it me, that I should give the inheritance of my fathers unto thee'. Jezebel's forged letters stage a fast and false blasphemy charges; Naboth is stoned, and Ahab takes the field. Elijah meets him: 'Hast thou killed, and also taken possession?... In the place where dogs licked the blood of Naboth shall dogs lick thy blood, even thine.'",
      zh: "\u4E9E\u54C8\u8CAA\u6200\u738B\u5BAE\u65C1\u62FF\u4F2F\u7684\u7956\u696D\u8461\u8404\u5712\uFF1B\u62FF\u4F2F\u62D2\u4E4B\uFF1A\u300C\u6211\u656C\u754F\u8036\u548C\u83EF\uFF0C\u842C\u4E0D\u6562\u5C07\u6211\u5148\u4EBA\u7559\u4E0B\u7684\u7522\u696D\u7D66\u4F60\u3002\u300D\u8036\u6D17\u5225\u507D\u9020\u66F8\u4FE1\u8A2D\u7981\u98DF\u8207\u5047\u7006\u795E\u4E4B\u7F6A\uFF1B\u62FF\u4F2F\u88AB\u77F3\u64CA\uFF0C\u4E9E\u54C8\u5F97\u7530\u3002\u4EE5\u5229\u4E9E\u8FCE\u4E4B\uFF1A\u300C\u4F60\u6BBA\u4E86\u4EBA\uFF0C\u53C8\u5F97\u4ED6\u7684\u7522\u696D\u9EBC\uFF1F\u2026\u2026\u72D7\u5728\u4F55\u8655\u8214\u62FF\u4F2F\u7684\u8840\uFF0C\u4E5F\u5FC5\u5728\u4F55\u8655\u8214\u4F60\u7684\u8840\u3002\u300D"
    },
    motifs: [
      "taboo-transgression",
      "boon-curse",
      "sacred-kingship"
    ],
    sensitivity: {
      restricted: false,
      note: "Canonical scripture of a living tradition; quoted from public-domain JPS 1917. Naboth's ancestral inheritance frames Israelite land law."
    },
    passages: [
      {
        id: "1",
        text: "And Ahab said unto Elijah: 'Hast thou found me, O mine enemy?' And he answered: 'I have found thee; because thou hast sold thyself to do that which is evil in the sight of the LORD. Behold, I will bring evil upon thee, and will utterly sweep away after thee; and will make thine house like the house of Jeroboam... because thou hast provoked Me to anger, and hast made Israel to sin.'",
        note: "Verbatim: JPS 1917, 1 Kings 21:20-22 (public domain), condensed."
      }
    ],
    persons: [
      "elijah"
    ]
