      zh: "\u897F\u5E95\u5BB6\u5341\u4E00\u5E74\uFF0C\u57CE\u88AB\u653B\u7834\uFF1B\u738B\u773E\u5B50\u5728\u4ED6\u773C\u524D\u88AB\u6BBA\uFF0C\u4ED6\u7684\u773C\u88AB\u525C\uFF0C\u5E36\u9396\u934A\u88AB\u64C4\u5230\u5DF4\u6BD4\u502B\u3002\u8036\u548C\u83EF\u7684\u6BBF\u3001\u738B\u5BAE\u3001\u5927\u5B85\u76E1\u711A\uFF1B\u57CE\u7246\u62C6\u6BC0\uFF1B\u8056\u6BBF\u7684\u5668\u76BF\u88AB\u5207\u6210\u9285\u584A\u64C4\u53BB\u3002\u57FA\u5927\u5229\u88AB\u7ACB\u7BA1\u9918\u6C11\u800C\u88AB\u6BBA\u2014\u2014\u773E\u4EBA\u61FC\u8FE6\u52D2\u5E95\u4EBA\uFF0C\u4E0B\u57C3\u53CA\u53BB\u3002\u300C\u9019\u6A23\uFF0C\u7336\u5927\u4EBA\u88AB\u64C4\u96E2\u958B\u672C\u5730\u3002\u300D"
