    sensitivity: {
      restricted: false,
      note: "Canonical hadith of a living tradition; presented as a paraphrase of the Arabic original; interfaith dimension noted for comparative study."
    },
    passages: [
      {
        id: "1",
        text: "A young Jewish boy used to serve the Prophet and used to fetch him water for ablution. One day the boy fell ill, and the Prophet went to visit him, sat near his head, and said to him: 'Embrace Islam.' The boy looked at his father, who was sitting with him, and the father said to him, 'Obey Abu al-Qasim.' And the boy embraced Islam. The Prophet went out of the house saying: 'Praise be to God who saved him from the Fire through me.'",
        note: "Paraphrase of Sahih al-Bukhari, Kitab al-Jana'iz, no. 1356; not verbatim."
      }
    ],
    persons: [
      "muhammad"
    ]
