    tradition: "hebrew",
    region: {
      en: "Susa, Persian royal citadel",
      zh: "\u66F8\u73CA\uFF0C\u6CE2\u65AF\u738B\u57CE"
    },
    lat: 32.19,
    lon: 48.26,
    period: "Narrative set c. 5th-4th c. BCE (Ahasuerus/Xerxes era); composed c. 4th-2nd c. BCE; principal MS: Leningrad Codex B19a (1008 CE)",
    source: {
      archive: "Sefaria (JPS 1917 translation)",
      work: "Esther 1-2, JPS Tanakh 1917",
      url: "https://www.sefaria.org/Esther.1.1"
    },
    category: "religious",
    license: "Public domain (JPS 1917)",
    summary: {
      en: "Ahasuerus's hundred-and-eighty-day banquet ends with Queen Vashti refusing to parade her beauty and losing her throne. Orphaned Hadassah, 'and her Hebrew name was Esther', is gathered into the harem of the citadel at Shushan under Mordecai's watch; she tells 'not her people nor her kindred, for Mordecai had charged her'. The king loves her above all the women, 'and he set the royal crown upon her head, and made her queen'. Mordecai overhears an assassination plot and is recorded in the chronicles.",
      zh: "\u4E9E\u54C8\u96A8\u9B6F\u4E00\u767E\u516B\u5341\u65E5\u5927\u5BB4\uFF0C\u738B\u540E\u74E6\u5BE6\u63D0\u62D2\u7D55\u5C55\u793A\u7F8E\u8C8C\u800C\u5931\u4F4D\u3002\u5B64\u5152\u54C8\u5927\u6C99\u2014\u2014\u5E0C\u4F2F\u4F86\u540D\u4EE5\u65AF\u5E16\u2014\u2014\u5728\u672B\u5E95\u6539\u56D1\u5490\u4E0B\u5165\u66F8\u73CA\u57CE\u5BAE\uFF0C'\u4E0D\u5C07\u7C4D\u8D2F\u5B97\u65CF\u544A\u8A34\u4EBA'\u3002\u738B\u611B\u5979\u904E\u65BC\u773E\u5973\uFF0C\u300C\u628A\u738B\u540E\u7684\u51A0\u5195\u6234\u5728\u5979\u982D\u4E0A\uFF0C\u7ACB\u5979\u70BA\u738B\u540E\u300D\u3002\u672B\u5E95\u6539\u5077\u807D\u5F12\u541B\u9670\u8B00\uFF0C\u4E8B\u8DE1\u8A18\u65BC\u738B\u4E0A\u8A18\u9304\u3002"
    },
