      zh: "\u62FF\u5F17\u4ED6\u5229\u652F\u6D3E\u88AB\u64C4\u7684\u591A\u6BD4\u5728\u4E9E\u8FF0\u7368\u884C\u4EC0\u4E00\u8207\u8CD9\u6FDF\uFF1B\u4ED6\u4E0D\u9867\u6027\u547D\u651C\u846C\u88AB\u6BBA\u7684\u4EE5\u8272\u5217\u4EBA\uFF0C\u9130\u820D\u8B4F\u7B11\uFF1A\u300C\u4ED6\u6015\u4EBA\u6BBA\u4ED6\uFF0C\u4F46\u9019\u6A23\u884C\u6709\u4F55\u76CA\u8655\uFF1F\u300D\u5728\u9662\u4E2D\u7761\u81E5\uFF0C\u96C0\u7CDE\u843D\u5165\u773C\u4E2D\u800C\u5931\u660E\uFF1B\u59BB\u5B50\u4E9E\u62FF\u505A\u50AD\u5DE5\uFF0C\u4ED6\u7684\u8CAC\u5099\u2014\u2014\u300C\u4E0D\u5982\u884C\u8CD9\u6FDF\u884C\u516C\u7FA9\u300D\u2014\u2014\u7D50\u675F\u9019\u90E8\u6190\u61AB\u4E4B\u66F8\u7684\u7B2C\u4E00\u5E55\u3002"
