      zh: "\u4E3B\u6559\u7D22\u798F\u7F85\u5C3C\u70CF\u65AF\u4EE5\u54C8\u91CC\u767C\u89AA\u81E8\u70BA\u689D\u4EF6\u4EA4\u57CE\u3002\u6B50\u746A\u723E\u651C\u4E00\u540D\u99F1\u99DD\u4F8D\u8005\u81EA\u9EA5\u5730\u90A3\u555F\u7A0B\uFF0C\u4E8C\u4EBA\u8F2A\u6D41\u9A0E\u4E58\u3002\u4ED6\u5F92\u6B65\u62AB\u88DC\u4E01\u6597\u7BF7\u5165\u57CE\uFF1B\u4E3B\u6559\u65BC\u5176\u8964\u8938\u4E2D\u8B80\u51FA\u4F46\u4EE5\u7406\u66F8\u4E4B\u8352\u6DBC\u53EF\u618E\u4E4B\u7269\u3002\u689D\u6B3E\u5BEC\u539A\uFF1A\u6559\u5802\u5F97\u4FDD\u3001\u7D0D\u7A05\u800C\u5B58\uFF1B\u54C8\u91CC\u767C\u65BC\u5927\u885B\u8056\u6240\u79AE\u62DC\uFF0C\u4E26\u6E05\u51FA\u963F\u514B\u85A9\u7684\u57CE\u4E2D\u7A62\u7269\u3002"
