    sensitivity: {
      restricted: false,
      note: "Early Islamic historiography; presented as received narrative."
    },
    passages: [
      {
        id: "1",
        text: "Ali marched against Mu'awiya, who had withheld his homage from Medina, and the armies met on the plain of Siffin by the Euphrates. For days the lines fought in relays; the spears and swords had decided nothing but the hour.",
        note: "Paraphrase of al-Tabari via Muir, The Caliphate (1891), ch. 20; not verbatim."
      },
      {
        id: "2",
        text: "Then Amr ibn al-As gave counsel to Mu'awiya: let the soldiers lift copies of the Qur'an on the points of their spears, crying, 'Let the Book of God judge between us.' And it was done; the battle stopped of itself. Ali said: 'I knew them \u2014 I tell you that these are the men of deception; by night they lifted pages that have nothing of the Qur'an in them.' But his army would not fight on, and compelled him to arbitration. The two arbitrators conferred at Adhruh; and the tide turned against Ali \u2014 and the strictest of his own soldiers broke away, crying, 'Judgment is God's alone; there is no arbitration between men.'",
        note: "Paraphrase of al-Tabari via Muir, The Caliphate (1891), ch. 20; not verbatim."
      }
    ],
    persons: [
      "ali"
    ]
