      zh: "\u570D\u56F0\u8005\u903C\u81F3\u5967\u65AF\u66FC\u5B85\uFF1B\u963F\u91CC\u9063\u5176\u5B50\u5B88\u9580\u3002\u53DB\u8005\u7D42\u7834\u9580\u800C\u5165\uFF1B\u5E74\u9081\u54C8\u91CC\u767C\u8AA6\u7D93\u6642\u88AB\u64CA\uFF1B\u5176\u8840\u6D41\u65BC\u7D93\u6587\u4E4B\u4E0A\u2014\u2014\u300E\u4E3B\u5FC5\u4F7F\u4F60\u514D\u53D7\u5632\u7B11\u8005\u4E4B\u5BB3\u300F\u2014\u2014\u7D93\u8AA6\u8B80\u81F3\u7D42\u3002\u9EA5\u5730\u90A3\u9996\u898B\u540C\u5BA4\u64CD\u6208\u4E4B\u8840\uFF1B\u76F8\u50B3\u5176\u8AA6\u8B80\u7684\u6284\u672C\uFF0C\u6B63\u662F\u4ED6\u4E3B\u6301\u59D4\u54E1\u6703\u6240\u5B9A\u3002"
