    license: "Public domain (Arabic originals medieval; English edition 1891)",
    summary: {
      en: "The Umayyad prince Abd al-Rahman, sole survivor of the massacre of his house, lands in Spain and builds his kingdom at Cordoba. Riding in the country of Ronda he finds a palm tree, the first he has seen since Damascus; he lays hold of it and speaks the lines the anthologies have kept: 'A palm like me, in exile far from home, parted from people and children... Turn to me, O palm, and hear me cry: as we are far from our people, so are you from yours.'",
      zh: "\u4F0D\u9EA5\u8449\u738B\u5B50\u963F\u5E03\u675C\xB7\u62C9\u8D6B\u66FC\u2014\u2014\u5176\u5BB6\u88AB\u5C60\u4E4B\u552F\u4E00\u5016\u5B58\u8005\u2014\u2014\u767B\u9678\u897F\u73ED\u7259\uFF0C\u5EFA\u90FD\u65BC\u79D1\u723E\u591A\u74E6\u3002\u884C\u65BC\u9686\u9054\u4E4B\u9109\uFF0C\u898B\u4E00\u68D5\u6ADA\uFF0C\u4E43\u5176\u81EA\u5927\u99AC\u58EB\u9769\u4EE5\u4F86\u6240\u898B\u9996\u682A\uFF1B\u4ED6\u57F7\u5176\u5E79\uFF0C\u8AA6\u51FA\u5F8C\u4E16\u6587\u96C6\u6240\u5B58\u4E4B\u53E5\uFF1A\u300E\u5982\u6211\u4E4B\u68D5\u6ADA\uFF0C\u96E2\u9109\u842C\u91CC\uFF0C\u8207\u65CF\u4EBA\u5B50\u5973\u76F8\u9694\u2026\u2026\u68D5\u6ADA\u554A\uFF0C\u8F49\u5411\u6211\uFF0C\u807D\u6211\u547C\u558A\uFF1A\u6211\u5011\u96E2\u65CF\u4EBA\u751A\u9060\uFF0C\u4F60\u4EA6\u96E2\u4F60\u7684\u65CF\u4EBA\u751A\u9060\u3002\u300F"
    },
    motifs: [
      "foundational-legend",
      "sacred-kingship",
      "boon-curse",
      "exile"
    ],
    sensitivity: {
      restricted: false,
      note: "Anecdote lore of the Umayyad exiles of Spain; the palm poem is among the most quoted texts of Andalusi tradition."
    },
    passages: [
      {
        id: "1",
        text: "Abd al-Rahman ibn Mu'awiya, the sole survivor of the Umayyad house after the Abbasid massacre, fled across half the world to Spain, and built his kingdom at Cordoba. Riding in the country of Ronda, he saw a palm tree \u2014 the first since Damascus \u2014 and laid hold of it, and spoke:",
        note: "Paraphrase of the anecdote and poem as preserved in the Arabic anthologies; not verbatim."
      },
      {
        id: "2",
        text: "'A palm like me, in exile far from home, parted from people and children, from kindred and from land: turn to me, O palm, and hear me cry \u2014 as we are far from our people, so are you from yours.' And the men of Spain wept to see their prince weep for a tree; and the kingdom of the exiles of Cordoba stood for three hundred years.",
        note: "Paraphrase of the anecdote and poem as preserved in the Arabic anthologies; not verbatim."
      }
    ],
    persons: []
