    title: {
      en: "The Golden Age of Knotted Cords (Zhuangzi)",
      zh: "\u7D50\u7E69\u800C\u7528\u4E4B\uFF1A\u81F3\u5FB7\u4E4B\u4E16\uFF08\u838A\u5B50\uFF09"
    },
    tradition: "taoist",
