      zh: "\u5927\u99AC\u58EB\u9769\u5BB0\u76F8\u81E8\u7D42\uFF0C\u56D1\u5176\u5B50\u4EE5\u66F8\u96A8\u846C\u3001\u5A36\u958B\u7F85\u5927\u81E3\u4E4B\u5973\u3002\u52AA\u723E\u4E01\xB7\u963F\u91CC\u8D74\u958B\u7F85\uFF0C\u4EE5\u5343\u91D1\u8CFC\u6B4C\u5973\u871C\u7CD6\u4E4B\u5149\uFF08\u963F\u59AE\u65AF\xB7\u8CC8\u5229\u65AF\uFF09\uFF0C\u6B78\u9014\u9047\u52AB\uFF1B\u5973\u5B50\u88AB\u89E3\u81F3\u5DF4\u683C\u9054\u737B\u7D66\u54C8\u91CC\u767C\uFF0C\u54C8\u91CC\u767C\u4E0D\u80AF\u7D0D\u2014\u2014\u56E0\u5979\u544A\u77E5\u5176\u6240\u5C6C\u3002\u6709\u60C5\u4EBA\u5F97\u5FA9\u805A\uFF1B\u6545\u4E8B\u4EE5\u5BAE\u5EF7\u4E4B\u516C\u7FA9\u4F5C\u7D50\u3002"
