    sensitivity: {
      restricted: false,
      note: "A tale of the Galland cycle, of Syrian storyteller origin; the most retold story of the Nights; paraphrased from the public-domain Burton translation."
    },
    passages: [
      {
        id: "1",
        text: "A lazy boy of the city is sent by an African sorcerer into a cave for a lamp; the boy keeps the ring, and the slave of the ring brings him home; then the lamp is rubbed, and its slave builds him a palace overnight, with a garden of jewels and a marriage to the sultan's daughter.",
        note: "Paraphrase of Burton, Supplemental Nights, vol. 6 (1888), 'Ala al-Din and the Magical Lamp'; not verbatim."
      },
      {
        id: "2",
        text: "The sorcerer returns in the dress of a lamp-seller, crying 'New lamps for old!'; the princess, who does not know the lamp's worth, gives it, and palace and bride are carried away to the Maghreb. The princess drugs the sorcerer's cup with the sleeping draught the boy brings her, and the boy returns, slays him, and has the palace set back where it stood.",
        note: "Paraphrase of Burton, Supplemental Nights, vol. 6 (1888); not verbatim."
      }
    ],
    persons: []
