    region: {
      en: "Mount Candorana and Benares (symbolic pin for the mountain)",
      zh: "\u65C3\u9640\u7F85\u5C71\u8207\u6CE2\u7F85\u5948\uFF08\u5C71\u70BA\u8C61\u5FB5\u6027\u5B9A\u4F4D\uFF09"
    },
    lat: 25.32,
