      zh: "\u4FF1\u76E7\u570B\u56E0\u9640\u7F85\u6CE2\u9054\u57CE\uFF1B\u9ED1\u5C71\u8207\u9F8D\u5BAE\uFF08\u8C61\u5FB5\u5B9A\u4F4D\uFF09"
