      zh: "\u5E1D\u91CB\u61C9\u5929\u754C\u5BBF\u9858\u9001\u4E0B\u300C\u5713\u6EFF\u5E03\u65BD\u300D\u7684\u9808\u5927\u62CF\u592A\u5B50\uFF1B\u56E0\u9951\u8352\u65BD\u6368\u7948\u96E8\u5BF6\u8C61\u800C\u906D\u653E\u9010\uFF0C\u651C\u59BB\u7F8E\u5E1D\u8207\u4E00\u96D9\u5152\u5973\u6D41\u653E\u6EAB\u8FE6\u5C71\uFF1B\u7E7C\u65BD\u8ECA\u99AC\uFF0C\u7D42\u5C07\u4E00\u5C0D\u5152\u5973\u65BD\u4E88\u8001\u5A46\u7F85\u9580\u9CE9\u8FE6\uFF0C\u4E43\u81F3\u5E1D\u91CB\u5047\u626E\u5A46\u7F85\u9580\u7D22\u5176\u59BB\uFF0C\u4EA6\u6B23\u7136\u8207\u4E4B\uFF1B\u5F8C\u56E0\u8AE6\u8A93\u4E4B\u529B\u3001\u5E1D\u91CB\u516B\u9858\u8207\u7956\u7236\u61FA\u6094\uFF0C\u4E00\u5BB6\u5718\u5713\uFF0C\u91CD\u767B\u738B\u4F4D\uFF0C\u5E1D\u91CB\u5FA9\u964D\u5BF6\u96E8\u5145\u76C8\u90FD\u57CE\u3002"
