    region: {
      en: "The root of the asvattha (Bodhi) tree at Uruvela, on the Neranjara (modern Bodh Gaya)",
      zh: "\u512A\u6A13\u983B\u87BA\u5C3C\u9023\u79AA\u6CB3\u7554\u83E9\u63D0\u6A39\u4E0B\uFF08\u4ECA\u83E9\u63D0\u4F3D\u8036\uFF09"
    },
    lat: 24.7,
