      zh: "\u6EAB\u4F2F\u96EA\u5B50\u9069\u9F4A\uFF0C\u820D\u65BC\u9B6F\uFF1B\u898B\u5BA2\u800C\u5606\u2014\u2014\u5176\u70BA\u4EBA\u4E5F\uFF0C\u52D5\u5BB9\u5176\u8272\uFF0C\u89F8\u76EE\u7686\u771F\u3002\u4EF2\u5C3C\u898B\u4E4B\u800C\u4E0D\u8A00\uFF1B\u66F0\uFF1A\u82E5\u592B\u4EBA\u8005\uFF0C\u76EE\u64CA\u800C\u9053\u5B58\u77E3\uFF0C\u4EA6\u4E0D\u53EF\u4EE5\u5BB9\u8072\u77E3\u3002"
