      zh: "\u5B50\u5217\u5B50\u7AAE\uFF0C\u5BB9\u8C8C\u6709\u98E2\u8272\uFF1B\u5BA2\u8A00\u4E4B\u65BC\u912D\u5B50\u967D\u3002\u5B50\u5217\u5B50\u7B11\u8B02\u5176\u59BB\u66F0\uFF1A\u541B\u975E\u81EA\u77E5\u6211\u4E5F\uFF0C\u4EE5\u4EBA\u4E4B\u8A00\u800C\u907A\u6211\u7C9F\u4E5F\u2014\u2014\u81F3\u65BC\u7F6A\u6211\u8005\uFF0C\u53C8\u4E14\u4EE5\u4EBA\u4E4B\u8A00\u3002"
