    category: "religious",
    region: {
      en: "The pass of Yin Hsi (symbolic pin: Hangu Pass, Lingbao, Henan, China)",
      zh: "\u51FD\u8C37\u95DC\uFF08\u8C61\u5FB5\u5B9A\u4F4D\uFF1A\u6CB3\u5357\u9748\u5BF6\uFF09"
    },
    lat: 34.53,
    lon: 110.85,
    period: "Tao Te Ching, c. 4th-3rd c. BCE (trans. Legge, 1891)",
